\set ON_ERROR_STOP on
BEGIN;

-- This fixture is reserved for the disposable ProductionReadiness database.
-- Refuse to run anywhere else; this prevents fixed smoke identities reaching a real tenant.
DO $$
BEGIN
  IF current_setting('barbersync.environment', true) IS DISTINCT FROM 'ProductionReadiness' THEN
    RAISE EXCEPTION 'production_readiness_seed.sql requires barbersync.environment=ProductionReadiness';
  END IF;
END $$;


-- ASP.NET Core Identity PasswordHasher V3 hash for the local-only password documented in the runbook.
-- The two operational smoke roles receive the schema's explicit permissions, never an auth bypass.

UPDATE barber.products SET category_id='70000000-0000-4000-8000-000000000095',usage_type='Both',unit='Unit',reorder_point=4 WHERE id='70000000-0000-4000-8000-000000000040' AND tenant_id='70000000-0000-4000-8000-000000000001';
-- IA operacional: metadados sintéticos, sem imagens, biometria ou credenciais reais.

-- Sprint 42 governance readiness. Fixed identifiers belong exclusively to ProductionReadiness.
VALUES('42420000-0000-4000-8000-000000000001','PRODUCTION_READINESS','Production Readiness','Plano técnico para validação de release',0,0,5,25,25,500,1024,'Active') ON CONFLICT(code) DO UPDATE SET updated_at=now();
SELECT '42420000-0000-4000-8000-000000000002',t.id,'42420000-0000-4000-8000-000000000001','Trial','Monthly',now(),now()+interval '30 days' FROM barber.tenants t WHERE t.name='ProductionReadiness' ON CONFLICT(id) DO NOTHING;
SELECT c.tenant_id,c.branch_id,c.id,x.key,x.title,x.title,'Pending' FROM barber.onboarding_checklists c CROSS JOIN (VALUES('branch','Cadastrar filial'),('services','Cadastrar serviços'),('professionals','Cadastrar profissionais'),('schedule','Configurar agenda'),('cash','Configurar caixa'),('inventory','Configurar produtos e estoque'),('payments','Configurar formas de pagamento'),('permissions','Configurar permissões'),('communication','Configurar comunicação'),('ai-operations','Configurar IA Operacional (opcional)')) x(key,title) WHERE c.id='42420000-0000-4000-8000-000000000004' ON CONFLICT(checklist_id,item_key) DO NOTHING;

-- Agenda Sprint 48: cenário controlado e idempotente, exclusivo de ProductionReadiness.

